SERIES="Alone · Oct 26–30"; WK="done-w2"
DAYS=[
dict(day="Mon",date="Oct 26",title="The Father Who Ran",reader="Theo",
 ref="Luke 15:20–24",verses=[(20,"And he arose and came to his father. But while he was still a long way off, his father saw him and felt compassion, and ran and embraced him and kissed him."),(21,"And the son said to him, ‘Father, I have sinned against heaven and before you. I am no longer worthy to be called your son.’"),(22,"But the father said to his servants, ‘Bring quickly the best robe, and put it on him, and put a ring on his hand, and shoes on his feet."),(23,"And bring the fattened calf and kill it, and let us eat and celebrate."),(24,"For this my son was dead, and is alive again; he was lost, and is found.’ And they began to celebrate.")],
 story_title="The lost son",story=[
 "Jesus told a story about a father who had two sons. One day the younger son said, “Dad, I don’t want to wait until you die. Give me my share of your money now.” That was a terrible thing to say. It was like telling his father, “I wish you were already gone.” But the father divided up his money and gave the younger son his share.",
 "The son packed up and moved to a faraway country. He spent every penny on parties and foolish living. Then a famine came, and he had nothing left. The only job he could find was feeding pigs, and he was so hungry he wished he could eat the pig food.",
 "Finally he came to his senses. “My father’s servants have plenty of bread, and I’m starving! I’ll go home and say, ‘Father, I have sinned. I’m not good enough to be your son anymore. Just let me be one of your workers.’” So he started the long walk home, practicing his speech.",
 "But while he was still far away, his father saw him. The father must have been watching the road every day. And he did something no proper man did in those days: he picked up his robe and <i>ran</i>. He threw his arms around his dirty, smelly son and kissed him. The son started his speech, but the father didn’t even let him finish. “Quick! Bring the best robe, a ring, and shoes! Let’s have a feast! My son was dead, and he’s alive again. He was lost, and now he’s found!”"],
 teach_title="Grace alone",
 teach=["The son came home with a plan to earn his way back. The father didn’t want his plan. He just wanted his son. That’s grace: God’s love we don’t deserve and can’t earn.","Last week Luther discovered this same thing. Our Father in heaven runs to us in Jesus, and He welcomes us home every time we come back sorry."],
 q=[("Josie & Louie","What did the father do when he saw his son coming? What gifts did he give him?"),("Junie & Theo","What was the son planning to say? Why didn’t the father let him finish?"),("Max","Why is it hard for people to believe God’s love is free? Is there anything that could make the Father stop watching the road for you?")],
 prayer="Heavenly Father, thank You for running to us in Jesus. Thank You that we don’t have to earn our way back to You.",
 ask="When we wander away, bring us home, and help us welcome others the way You welcome us.",
 bless="You are baptized. Your Father always runs to welcome you home.",
 kids=dict(lede="The lost son came home, and his father ran to hug him and threw a party! That’s how God loves us: by grace alone.",
  blanks=["The younger son spent all his ___.","He took a job feeding ___.","His father ___ to meet him.","The father gave him a robe and a ___.","God’s love we don’t earn is called ___."],bank=["ran","grace","pigs","money","ring"],ans=["money","pigs","ran","ring","grace"],
  words=["FATHER","SON","GRACE","HOME","RING","ROBE","FEAST"],
  quiz=[("Did the son have to earn his way back?",["Yes","No"]),("God’s love is…",["A free gift","A reward"])],qa=[1,0],
  draw="Draw the party the father threw when his son came home.",mv=("Luke 15:24","“He was lost, and is found.”"))),
dict(day="Tue",date="Oct 27",title="Count the Stars",reader="Junie",
 ref="Genesis 15:5–6",verses=[(5,"And he brought him outside and said, “Look toward heaven, and number the stars, if you are able to number them.” Then he said to him, “So shall your offspring be.”"),(6,"And he believed the LORD, and he counted it to him as righteousness.")],
 story_title="Abraham’s promise",story=[
 "A long time ago, God spoke to a man named Abram. (Later God changed his name to Abraham.) God said, “Leave your home and go to a land I will show you. I will make you into a great nation, and through you all the families of the earth will be blessed.” So Abram packed up his tents and animals and left, not knowing exactly where he was going.",
 "But there was one big problem. Abram and his wife Sarai had no children, and they were getting old. How could Abram become a great nation without even one child? Years went by, and still no baby. Abram began to worry. “Lord,” he said, “You haven’t given me any children. Is a servant going to get everything when I die?”",
 "So one night, God brought Abram outside his tent. “Look up at the sky,” God said. “Count the stars, if you can.” Abram looked up. There were no city lights back then, so the sky was packed with more stars than anyone could ever count. Then God said, “That’s how many children and grandchildren and great-grandchildren you will have.”",
 "Abram was old. Nothing about it made sense. But the Bible says: “He believed the LORD, and He counted it to him as righteousness.” Abram didn’t do anything to earn it. He simply trusted God’s promise, and God counted him as right. Many years later, when Abraham was 100 years old, God kept His promise, and baby Isaac was born. And from Abraham’s family, Jesus Himself would one day come."],
 teach_title="Faith alone",
 teach=["Faith means trusting God’s promise, even when we can’t see how it will happen. Abraham didn’t become right with God by being good. He trusted, and God counted it as righteousness. Paul uses this exact verse in Romans 4 to teach that we are saved by faith.","And even our faith is God’s gift. He creates it through His Word, like a promise spoken under the stars."],
 q=[("Josie & Louie","What did God tell Abram to count? How many stars could he count?"),("Junie & Theo","Why was it hard for Abram to believe God’s promise? What did God count as righteousness?"),("Max","Faith isn’t a feeling. It’s trusting a promise. What promise of God is hardest for you to trust right now?")],
 prayer="Faithful God, thank You for keeping Your promise to Abraham and sending Jesus through his family. Thank You for giving us faith to trust You.",
 ask="When Your promises are hard to believe, strengthen our faith.",
 bless="You are baptized. God keeps every promise He makes to you.",
 kids=dict(lede="God told Abraham to count the stars. Abraham believed God’s promise, and God counted him righteous by faith alone!",
  blanks=["God told Abram to count the ___.","Abram and Sarai had no ___.","Abram ___ the Lord.","Their son was named ___.","We are saved through ___."],bank=["Isaac","stars","faith","believed","children"],ans=["stars","children","believed","Isaac","faith"],
  words=["STARS","FAITH","PROMISE","ABRAHAM","ISAAC","TRUST","TENT"],
  quiz=[("Could Abram count all the stars?",["Yes","No"]),("Faith means…",["Trusting God","Being perfect"])],qa=[1,0],
  draw="Draw a night sky full of stars. Write a promise from God in the middle.",mv=("Genesis 15:6","“He believed the LORD, and he counted it to him as righteousness.”"))),
dict(day="Wed",date="Oct 28",title="It Is Written",reader="Max",
 ref="Matthew 4:1–4",verses=[(1,"Then Jesus was led up by the Spirit into the wilderness to be tempted by the devil."),(2,"And after fasting forty days and forty nights, he was hungry."),(3,"And the tempter came and said to him, “If you are the Son of God, command these stones to become loaves of bread.”"),(4,"But he answered, “It is written, “‘Man shall not live by bread alone, but by every word that comes from the mouth of God.’”")],
 story_title="Jesus in the wilderness",story=[
 "Right after Jesus was baptized in the Jordan River, the Holy Spirit led Him out into the wilderness: a hot, dry, rocky desert with no food and no people. Jesus stayed there forty days and forty nights without eating anything. You can imagine how hungry He was.",
 "That’s when the devil came. He pointed at the stones on the ground. “If You are the Son of God, turn these stones into bread.” Jesus could have done it easily. But Jesus answered with God’s Word: “It is written, ‘Man shall not live by bread alone, but by every word that comes from the mouth of God.’”",
 "So the devil tried again. He took Jesus to the very top of the temple. “Jump! The Bible says God’s angels will catch You.” The devil was even quoting Scripture, twisting it to trick Jesus. But Jesus answered, “It is also written, ‘You shall not put the Lord your God to the test.’”",
 "One last time, the devil showed Jesus all the kingdoms of the world. “I’ll give You all of this, if You just bow down and worship me.” Jesus said, “Be gone, Satan! For it is written, ‘You shall worship the Lord your God and Him only shall you serve.’” And the devil left Him, and angels came and took care of Jesus.",
 "Three times the devil attacked, and three times Jesus fought back with the same weapon: “It is written.”"],
 teach_title="Scripture alone",
 teach=["Jesus didn’t win with clever arguments or a feeling. He used God’s Word. That’s what Luther meant by Scripture alone: God’s Word is the final say, above any person, any king, or any trick of the devil.","Ephesians 6 calls God’s Word “the sword of the Spirit.” And notice where Jesus won: in the very place Adam and Eve, and all of us, have lost. He resisted for us."],
 q=[("Josie & Louie","What did the devil want Jesus to turn into bread? What did Jesus say every time?"),("Junie & Theo","Why do you think Jesus answered with Bible verses instead of His own words? What Bible verse do you know by heart?"),("Max","The devil quoted Scripture too, but twisted it. How can we tell when someone is using the Bible the wrong way? What “stones into bread” temptations do you face?")],
 prayer="Lord Jesus, thank You for standing strong against the devil for us. Thank You for Your Word, which is stronger than any temptation.",
 ask="Put Your Word in our hearts, so we can say “It is written” when we are tempted.",
 bless="You are baptized. God’s Word is your sword and shield.",
 kids=dict(lede="Three times the devil tried to trick Jesus, and three times Jesus answered, “It is written!” God’s Word is our final say.",
  blanks=["Jesus was in the ___ for forty days.","The devil said to turn ___ into bread.","Jesus answered, “It is ___.”","Jesus used God’s ___.","The devil went away, and ___ came to help Jesus."],bank=["written","wilderness","angels","stones","Word"],ans=["wilderness","stones","written","Word","angels"],
  words=["WRITTEN","WORD","DESERT","STONES","BREAD","SWORD","JESUS"],
  quiz=[("Did Jesus turn the stones into bread?",["Yes","No"]),("How did Jesus fight the devil?",["With God’s Word","With His fists"])],qa=[1,0],
  draw="Draw a sword. On it, write a Bible verse you know.",mv=("Matthew 4:4","“Man shall not live by bread alone, but by every word that comes from the mouth of God.”"))),
dict(day="Thu",date="Oct 29",title="Remember Me",reader="Theo",
 ref="Luke 23:39–43",verses=[(39,"One of the criminals who were hanged railed at him, saying, “Are you not the Christ? Save yourself and us!”"),(40,"But the other rebuked him, saying, “Do you not fear God, since you are under the same sentence of condemnation?"),(41,"And we indeed justly, for we are receiving the due reward of our deeds; but this man has done nothing wrong.”"),(42,"And he said, “Jesus, remember me when you come into your kingdom.”"),(43,"And he said to him, “Truly, I say to you, today you will be with me in paradise.”")],
 story_title="The thief on the cross",story=[
 "On the day Jesus died, He wasn’t alone on the hill called Calvary. Two criminals were crucified with Him, one on His right and one on His left. They had done terrible things, and now they were being punished.",
 "Crowds stood around making fun of Jesus. “He saved others! Let Him save Himself!” Even one of the criminals joined in, sneering, “Aren’t You the Christ? Save Yourself, and us too!”",
 "But the other criminal spoke up. “Don’t you fear God? We deserve this. We’re getting what our actions earned. But this man hasn’t done anything wrong.” Then he turned his head toward Jesus and said, “Jesus, remember me when You come into Your kingdom.”",
 "Think about it: this man had no time left to fix his life. He couldn’t go to church, give money, or make up for what he’d done. His hands and feet were nailed down. All he could do was ask Jesus. And Jesus answered him with one of the most beautiful promises in the whole Bible: “Truly, I say to you, today you will be with Me in paradise.”"],
 teach_title="Christ alone",
 teach=["The thief had nothing to offer but his need. Jesus was enough. We are saved by Christ alone: not by Jesus plus our good works, plus the saints, or plus anything else.","That’s the center of everything the Reformation was about. Grace, faith, and Scripture all point to one person: Jesus, who died for the thief and for us."],
 q=[("Josie & Louie","What did the second thief ask Jesus? Where did Jesus say he would go?"),("Junie & Theo","What could the thief do to earn heaven? Why did Jesus say yes to him anyway?"),("Max","Some people say deathbed faith isn’t fair. Why does this story actually show how grace works? What does “Christ alone” rule out?")],
 prayer="Lord Jesus, remember us, as You remembered the thief on the cross. Thank You for dying for us, and for being all we need.",
 ask="Help us trust You alone, and never think we have to add anything to what You did.",
 bless="You are baptized. Jesus remembers you, and you will be with Him in paradise.",
 kids=dict(lede="A thief on the cross asked Jesus to remember him, and Jesus promised him paradise. We are saved by Christ alone!",
  blanks=["Two ___ were on crosses next to Jesus.","One thief said, “Jesus, ___ me.”","Jesus promised he would be in ___.","The thief could not do anything to ___ heaven.","We are saved by ___ alone."],bank=["paradise","remember","earn","Christ","criminals"],ans=["criminals","remember","paradise","earn","Christ"],
  words=["CROSS","CHRIST","PARADISE","REMEMBER","TODAY","KINGDOM","THIEF"],
  quiz=[("Did the thief do good works to get to heaven?",["Yes","No"]),("Who saves us?",["Jesus alone","Jesus plus us"])],qa=[1,0],
  draw="Draw the three crosses on the hill, with Jesus in the middle.",mv=("Luke 23:43","“Today you will be with me in paradise.”"))),
dict(day="Fri",date="Oct 30",title="A Great Cloud of Witnesses",reader="Max",
 ref="Hebrews 12:1–2",verses=[(1,"Therefore, since we are surrounded by so great a cloud of witnesses, let us also lay aside every weight, and sin which clings so closely, and let us run with endurance the race that is set before us,"),(2,"looking to Jesus, the founder and perfecter of our faith, who for the joy that was set before him endured the cross, despising the shame, and is seated at the right hand of the throne of God.")],
 story_title="Reformation Day and All Saints’ Day",story=[
 "Tomorrow, October 31, is Reformation Day, the day Luther nailed up his 95 Theses. And the very next day, November 1, is All Saints’ Day. Luther picked October 31 on purpose: the night before All Saints’, when lots of people would be at church.",
 "Ten years after the 95 Theses, in 1527, a deadly disease called the plague came to Wittenberg. Most people who could leave, did. The university moved away. Luther’s prince ordered him to leave too. But Luther stayed. He said a pastor shouldn’t run away when his people needed him. Martin and Katie opened their home and cared for the sick, even while Katie was expecting a baby.",
 "Some of the people they loved died that year. In those hard days, Luther wrote a hymn based on Psalm 46, the psalm we read last week: “A mighty fortress is our God, a trusty shield and weapon.” Its last verse says that even if they take our bodies, goods, honor, child, and spouse, “the kingdom ours remaineth.”",
 "That’s what All Saints’ Day is about. In the church, a “saint” is any believer in Jesus. On All Saints’ we remember the Christians who have died in the faith: people from the Bible, people like Luther and Katie, and people we know and love. They aren’t gone. They’re with Jesus. Hebrews says they’re like a great crowd cheering us on in a race, as we keep running toward Jesus too."],
 teach_title="Running the race",
 teach=["The saints who died in Christ are with Him now, and we’ll see them again at the resurrection. We don’t pray to them or talk to them, but we thank God for them and follow their faith.","Every time we receive the Lord’s Supper, we join “with angels and archangels and with all the company of heaven.” We’re all one family in Jesus."],
 q=[("Josie & Louie","What is a saint? Who are the saints cheering for?"),("Junie & Theo","Why did Luther stay in Wittenberg when the plague came? Who is someone we know who is with Jesus now?"),("Max","Hebrews says to run with endurance, looking to Jesus. What does a runner have to lay aside to finish? What’s weighing you down in your race of faith?")],
 prayer="Almighty God, thank You for Martin Luther and for all Your saints who have finished the race and now rest with Jesus. Thank You for the people we love who are with You now.",
 ask="Help us lay aside every weight and keep running, looking to Jesus, until we see them again.",
 bless="You are baptized. You are one of God’s saints, now and forever.",
 kids=dict(lede="Tomorrow is Reformation Day, and Sunday is All Saints’ Day! We thank God for all the believers who are now with Jesus.",
  blanks=["Reformation Day is October ___.","All Saints’ Day is November ___.","Luther wrote “A Mighty ___ Is Our God.”","A saint is anyone who believes in ___.","We run the race looking to ___."],bank=["1","Jesus","31","Fortress","Jesus"],ans=["31","1","Fortress","Jesus","Jesus"],
  words=["SAINTS","RACE","CLOUD","FORTRESS","HEAVEN","JESUS","RUN"],
  quiz=[("Do people become angels when they die?",["Yes","No"]),("All Saints’ Day remembers…",["Believers with Jesus","Only famous people"])],qa=[1,0],
  draw="Draw someone you love who is with Jesus now, or draw the great crowd of saints cheering.",mv=("Hebrews 12:1","“Let us run with endurance the race that is set before us.”"))),
]
